  params: Promise<{ id: string }>
}

interface PostInput {
  title?: string
  content?: string
}

function isPostInput(value: unknown): value is PostInput {
  if (typeof value !== 'object' || value === null) {
    return false
  }

  const input = value as Record<string, unknown>
  return (
    (input.title === undefined || typeof input.title === 'string') &&
    (input.content === undefined || typeof input.content === 'string')
  )
}

async function readPostInput(request: Request): Promise<PostInput | null> {
  try {
    const body: unknown = await request.json()
    return isPostInput(body) ? body : null
  } catch {
    return null
  }
}

export async function GET(_request: Request, { params }: RouteContext) {
