import { NextResponse } from 'next/server'

interface RouteContext {
  params: Promise<{ id: string }>
}

interface PostInput {
  title?: string
  content?: string
}

function isPostInput(value: unknown): value is PostInput {
  if (typeof value !== 'object' || value === null) {
    return false
  }

  const input = value as Record<string, unknown>
  return (
    (input.title === undefined || typeof input.title === 'string') &&
    (input.content === undefined || typeof input.content === 'string')
  )
}

async function readPostInput(request: Request): Promise<PostInput | null> {
  try {
    const body: unknown = await request.json()
    return isPostInput(body) ? body : null
  } catch {
    return null
  }
}

export async function GET(_request: Request, { params }: RouteContext) {
  const { id } = await params
  const postId = Number.parseInt(id, 10)
  const post = {
    id: postId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post)
}

export async function PUT(request: Request, { params }: RouteContext) {
  const { id } = await params
  const body = await readPostInput(request)

  if (!body) {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 })
  }

  const postId = Number.parseInt(id, 10)
  const updatedPost = {
    id: postId,
    title: body.title || `Post ${id}`,
    content: body.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost)
}

export async function DELETE(_request: Request, { params }: RouteContext) {
  const { id } = await params
  return NextResponse.json({ message: `Post ${id} deleted successfully` })
}

